// Package schema defines the ent schema for VaxBook's Postgres database.
package schema

import (
	"time"

	"entgo.io/ent"
	"entgo.io/ent/schema/field"
	"entgo.io/ent/schema/mixin"
	"github.com/google/uuid"
)

// newID returns a UUIDv7 (SAD §6.1: every primary key is a UUIDv7).
func newID() uuid.UUID { return uuid.Must(uuid.NewV7()) }

// idMixin gives an entity a UUIDv7 primary key generated by the application.
type idMixin struct{ mixin.Schema }

func (idMixin) Fields() []ent.Field {
	return []ent.Field{
		field.UUID("id", uuid.UUID{}).Default(newID).Immutable(),
	}
}

// createdAtMixin records when a row was created.
type createdAtMixin struct{ mixin.Schema }

func (createdAtMixin) Fields() []ent.Field {
	return []ent.Field{
		field.Time("created_at").Default(time.Now).Immutable(),
	}
}
